const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const countryName = 'Zimbabwe';
  const geometry = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', countryName))
    .geometry();

  const startDate2023 = '2023-02-01';
  const endDate2023 = '2023-02-28';
  const startDate2024 = '2024-02-01';
  const endDate2024 = '2024-02-29'; // 2024 is a leap year

  // 2. Data Acquisition
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');

  const collection2023 = chirps
    .filterDate(startDate2023, endDate2023)
    .filterBounds(geometry);

  const collection2024 = chirps
    .filterDate(startDate2024, endDate2024)
    .filterBounds(geometry);

  // 3. Data Availability Check
  const size2023 = collection2023.size().getInfo();
  const size2024 = collection2024.size().getInfo();

  if (size2023 === 0 || size2024 === 0) {
    console.log(`Image count for Feb 2023: ${size2023}`);
    console.log(`Image count for Feb 2024: ${size2024}`);
    console.log('C1: Empty Collection');
    return;
  }
  console.log(`Image count for Feb 2023: ${size2023}`);
  console.log(`Image count for Feb 2024: ${size2024}`);

  // 4. Processing & Calculation
  const totalRainfall2023 = collection2023.select('precipitation').sum();
  const totalRainfall2024 = collection2024.select('precipitation').sum();

  const scale = 5000; // CHIRPS native resolution is approx. 5.5km

  const meanRainfall2023 = totalRainfall2023.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation');

  const meanRainfall2024 = totalRainfall2024.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation');

  // Check for valid pixels during reduction
  const pixelCount = totalRainfall2023.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  if (pixelCount === 0) {
      console.log('No valid pixels found within the geometry.');
      console.log('C2: No Valid Pixels');
      return;
  }
  console.log(`Valid pixels counted: ${pixelCount}`);

  // 5. Validation & Final Answer
  const val2023 = meanRainfall2023.getInfo();
  const val2024 = meanRainfall2024.getInfo();

  if (val2023 === null || val2024 === null) {
    console.log('Calculation resulted in null.');
    console.log('C3: Calculation Failure');
    return;
  }

  console.log(`Total Mean Rainfall Feb 2023: ${val2023.toFixed(2)} mm`);
  console.log(`Total Mean Rainfall Feb 2024: ${val2024.toFixed(2)} mm`);

  if (val2024 < val2023) {
    console.log('Evidence: Rainfall in Feb 2024 was lower than in Feb 2023.');
    console.log('A');
  } else {
    console.log('Evidence: Rainfall in Feb 2024 was not lower than in Feb 2023.');
    console.log('B');
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Error during Earth Engine analysis: ${e}`);
    console.log('D');
  }
}

initEE();
